# CUDA source implementing half‑precision GEMM C = A * Bᵀ
_cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int TILE>
__global__ void matmul_fp16_kernel(const __half* __restrict__ A,
                                   const __half* __restrict__ B,
                                   __half* __restrict__ C,
                                   int M, int K, int N) {
    // Shared‑memory tiles
    __shared__ __half As[TILE][TILE];
    __shared__ __half Bs[TILE][TILE];

    int row = blockIdx.y * TILE + threadIdx.y; // index in M dimension
    int col = blockIdx.x * TILE + threadIdx.x; // index in N dimension

    float acc = 0.0f;
    int tiles = (K + TILE - 1) / TILE;

    for (int t = 0; t < tiles; ++t) {
        // Global indices for the tiles of A and B (B is stored as N×K)
        int a_row = row;
        int a_col = t * TILE + threadIdx.x;
        int b_row = col;                // corresponds to output column index
        int b_col = t * TILE + threadIdx.y;

        // Load A tile
        As[threadIdx.y][threadIdx.x] = (a_row < M && a_col < K)
            ? A[a_row * K + a_col] : __float2half(0.0f);
        // Load B tile (note the transposed access)
        Bs[threadIdx.y][threadIdx.x] = (b_row < N && b_col < K)
            ? B[b_row * K + b_col] : __float2half(0.0f);

        __syncthreads();

        #pragma unroll
        for (int i = 0; i < TILE; ++i) {
            acc += __half2float(As[threadIdx.y][i]) *
                   __half2float(Bs[i][threadIdx.x]);
        }
        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2,
                "Model expects 2‑D tensors");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
                "All tensors must be fp16");
    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(),
                "Tensors must be contiguous");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    int64_t N = B.size(0);        // B is (N, K); we need Bᵀ (K, N)

    auto C = torch::empty({M, N}, A.options());

    const int TILE = 16;
    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (M + TILE - 1) / TILE);

    AT_DISPATCH_HALF_TYPES(A.scalar_type(), "matmul_fp16", [&] {
        matmul_fp16_kernel<TILE><<<grid, block>>>(
            reinterpret_cast<const __half*>(A.data_ptr<scalar_t>()),
            reinterpret_cast<const __half*>(B.data_ptr<scalar_t>()),
            reinterpret_cast<__half*>(C.data_ptr<scalar_t>()),
            static_cast<int>(M), static_cast<int>(K), static_cast<int>(N));
    });

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA kernel launch failed: ", cudaGetErrorString(err));
    }
    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "Half‑precision GEMM (CUDA)");
}
'''

# Compile the inline extension
_matmul_ext = load_inline(name='matmul_fp16_ext',
                          cpp_sources='',
                          cuda_sources=_cuda_source,
                          functions=['matmul_fp16'],
                          verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs C = A @ B.T using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matmul_ext.matmul_fp16(A, B)

# Helper functions matching the reference script
M = 1024 * 2
K = 4096 * 2
N = 2048 * 2

def get_inputs():
    A = torch.rand(M, K, dtype=torch.float16, device='cuda')
    B = torch.rand(N, K, dtype=torch.float16, device='cuda')
    return [A, B]

def get_init_inputs():
    return []  # No special initialization needed
